/*
 * Tecton design tokens (raw, framework-neutral).
 *
 * Values transcribed from the Tecton Storybook captures in `tecton-screenshots/`
 * (Foundations > Colors / Spacing and Corner Radii / Typography pages).
 * Variable names were reconstructed from the visible `--tecton-…` prefix plus the
 * source token path (`semantic.color.*`, `foundational.scale.*`) because the CSS
 * variable column is truncated in the captures; values are fully legible and exact.
 *
 * Tecton MUI v1.0 only ships a dark theme, so these are the canonical (dark) values.
 * Replace this file verbatim with the generated CSS export when it is available.
 *
 * Do not consume these directly in components: the shadcn variables in
 * `tecton-theme.css` / `globals.css` are the public theming contract.
 */

:root {
  /* ---------------------------------------------------------------------- */
  /* Text — semantic.color.text.*                                            */
  /* ---------------------------------------------------------------------- */
  --tecton-color-text-primary: #f6f5f8;
  --tecton-color-text-secondary: #a7a2ac;
  --tecton-color-text-disabled: #545356;
  --tecton-color-text-placeholder: #6a696c;
  --tecton-color-text-inverse: #131214;
  --tecton-color-text-subtlest: #89848e;

  /* ---------------------------------------------------------------------- */
  /* Surfaces — semantic.color.surface.* / semantic.color.divider.*          */
  /* ---------------------------------------------------------------------- */
  --tecton-color-bg-default: #1d1c1f;
  --tecton-color-bg-paper: #131214;
  --tecton-color-bg-elevated: #131214;
  --tecton-color-divider-subtle: #342f39;
  --tecton-color-divider-medium: #57515c;
  --tecton-color-divider-strong: #6e6873;

  /* ---------------------------------------------------------------------- */
  /* Actions — semantic.color.roles.action.*                                 */
  /* ---------------------------------------------------------------------- */
  /* primary (filled) */
  --tecton-color-action-primary-bg: #5d4d68;
  --tecton-color-action-primary-text: #e5e0eb;
  --tecton-color-action-primary-hover-bg: #74647f;
  --tecton-color-action-primary-focus-bg: #74647f;
  --tecton-color-action-primary-pressed-bg: #80708b;
  --tecton-color-action-primary-active-bg: #80708b;
  --tecton-color-action-primary-hover-text: #ffffff;
  --tecton-color-action-primary-focus-text: #ffffff;
  --tecton-color-action-primary-pressed-text: #ffffff;
  --tecton-color-action-primary-active-text: #ffffff;
  --tecton-color-action-primary-adornment: #beb1c8;
  --tecton-color-action-primary-hover-adornment: #ffffffb3;
  --tecton-color-action-primary-focus-adornment: #ffffffb3;
  --tecton-color-action-primary-pressed-adornment: #ffffffcc;
  --tecton-color-action-primary-active-adornment: #ffffffcc;

  /* secondary (filled) */
  --tecton-color-action-secondary-bg: #3a343e;
  --tecton-color-action-secondary-text: #bab3c0;
  --tecton-color-action-secondary-hover-bg: #514659;
  --tecton-color-action-secondary-focus-bg: #514659;
  --tecton-color-action-secondary-pressed-bg: #5a4f62;
  --tecton-color-action-secondary-active-bg: #5a4f62;
  --tecton-color-action-secondary-hover-text: #e4e0ea;
  --tecton-color-action-secondary-focus-text: #e4e0ea;
  --tecton-color-action-secondary-pressed-text: #efecf3;
  --tecton-color-action-secondary-active-text: #efebf4;
  --tecton-color-action-secondary-adornment: #9a91a2;
  --tecton-color-action-secondary-hover-adornment: #cbc4d5;
  --tecton-color-action-secondary-focus-adornment: #cbc4d5;
  --tecton-color-action-secondary-pressed-adornment: #cac5d2;
  --tecton-color-action-secondary-active-adornment: #cdc4d8;

  /* tertiary (transparent) */
  --tecton-color-action-tertiary-bg: #00000000;
  --tecton-color-action-tertiary-text: #bab3c0;
  --tecton-color-action-tertiary-hover-bg: #3a343e;
  --tecton-color-action-tertiary-focus-bg: #3a343e;
  --tecton-color-action-tertiary-pressed-bg: #433d47;
  --tecton-color-action-tertiary-active-bg: #433d47;
  --tecton-color-action-tertiary-hover-text: #cac5d2;
  --tecton-color-action-tertiary-focus-text: #cac5d2;
  --tecton-color-action-tertiary-pressed-text: #e3e0e8;
  --tecton-color-action-tertiary-active-text: #e3e0e8;
  --tecton-color-action-tertiary-adornment: #9a91a2;
  --tecton-color-action-tertiary-hover-adornment: #bcb2c4;
  --tecton-color-action-tertiary-focus-adornment: #bcb2c4;
  --tecton-color-action-tertiary-pressed-adornment: #cac5d2;
  --tecton-color-action-tertiary-active-adornment: #cbc4d5;

  /* outlined */
  --tecton-color-action-outlined-bg: #00000000;
  --tecton-color-action-outlined-border: #5a4f62;
  --tecton-color-action-outlined-strong-border: #aaa1b2;
  --tecton-color-action-outlined-text: #aaa1b2;
  --tecton-color-action-outlined-hover-bg: #433d47;
  --tecton-color-action-outlined-focus-bg: #433d47;
  --tecton-color-action-outlined-pressed-bg: #4e4853;
  --tecton-color-action-outlined-active-bg: #4e4853;
  --tecton-color-action-outlined-hover-border: #cac5d2;
  --tecton-color-action-outlined-focus-border: #cac5d2;
  --tecton-color-action-outlined-pressed-border: #d8d5de;
  --tecton-color-action-outlined-active-border: #d9d5e1;
  --tecton-color-action-outlined-hover-text: #e4e0ea;
  --tecton-color-action-outlined-focus-text: #e4e0ea;
  --tecton-color-action-outlined-pressed-text: #efecf3;
  --tecton-color-action-outlined-active-text: #efebf4;
  --tecton-color-action-outlined-adornment: #8b8293;
  --tecton-color-action-outlined-hover-adornment: #cbc4d5;
  --tecton-color-action-outlined-focus-adornment: #cbc4d5;
  --tecton-color-action-outlined-pressed-adornment: #d8d5de;
  --tecton-color-action-outlined-active-adornment: #d9d5e1;

  /* text only */
  --tecton-color-action-text-only-text: #9a91a2;
  --tecton-color-action-text-only-focus-bg: #00000080;
  --tecton-color-action-text-only-hover-text: #bcb2c4;
  --tecton-color-action-text-only-focus-text: #bcb2c4;
  --tecton-color-action-text-only-pressed-text: #beb1c8;
  --tecton-color-action-text-only-active-text: #beb1c8;
  --tecton-color-action-text-only-adornment: #716679;
  --tecton-color-action-text-only-hover-adornment: #8e8199;
  --tecton-color-action-text-only-focus-adornment: #8e8199;
  --tecton-color-action-text-only-pressed-adornment: #90809e;
  --tecton-color-action-text-only-active-adornment: #90809e;

  /* disabled — semantic.color.roles.disabled.* */
  --tecton-color-action-disabled-filled-bg: #00000066;
  --tecton-color-action-disabled-filled-text: #545356;
  --tecton-color-action-disabled-filled-adornment: #403f42;
  --tecton-color-action-disabled-outline-bg: #00000000;
  --tecton-color-action-disabled-outline-border: #323134;
  --tecton-color-action-disabled-outline-text: #4b4a4d;
  --tecton-color-action-disabled-outline-adornment: #403f42;
  --tecton-color-action-disabled-text-only-text: #4b4a4d;
  --tecton-color-action-disabled-text-only-adornment: #403f42;

  /* focus — semantic.color.focusOutline */
  --tecton-color-focus-ring: #ff52a8;

  /* ---------------------------------------------------------------------- */
  /* Status — semantic.color.roles.{success,error,warning,info,neutral}.*    */
  /* ---------------------------------------------------------------------- */
  --tecton-color-status-success-main: #78c692;
  --tecton-color-status-success-bright: #ace4bd;
  --tecton-color-status-success-muted: #217846;
  --tecton-color-status-success-filled-bg: #4fa66f;
  --tecton-color-status-success-filled-text: #001607;
  --tecton-color-status-success-filled-adornment: #001607;
  --tecton-color-status-success-filled-hover-bg: #61b67f;
  --tecton-color-status-success-filled-pressed-bg: #78c692;
  --tecton-color-status-success-outline-bg: #00000000;
  --tecton-color-status-success-outline-strong-border: #78c692;
  --tecton-color-status-success-outline-text: #92d6a8;
  --tecton-color-status-success-outline-adornment: #78c692;
  --tecton-color-status-success-outline-hover-border: #61b67f;
  --tecton-color-status-success-outline-pressed-border: #92d6a8;

  --tecton-color-status-error-main: #c16e6c;
  --tecton-color-status-error-bright: #e3a6a6;
  --tecton-color-status-error-muted: #832d28;
  --tecton-color-status-error-filled-bg: #c16e6c;
  --tecton-color-status-error-filled-text: #2e0000;
  --tecton-color-status-error-filled-adornment: #2e0000;
  --tecton-color-status-error-filled-hover-bg: #d89291;
  --tecton-color-status-error-filled-pressed-bg: #e3a6a6;
  --tecton-color-status-error-outline-bg: #00000000;
  --tecton-color-status-error-outline-strong-border: #cc7f7d;
  --tecton-color-status-error-outline-text: #cc7f7d;
  --tecton-color-status-error-outline-adornment: #cc7f7d;
  --tecton-color-status-error-outline-hover-border: #d89291;
  --tecton-color-status-error-outline-pressed-border: #ecbbbc;
  --tecton-color-status-error-outline-active-border: #e3a6a6;

  --tecton-color-status-warning-main: #f9a308;
  --tecton-color-status-warning-bright: #fddf91;
  --tecton-color-status-warning-muted: #995b04;
  --tecton-color-status-warning-filled-bg: #e59306;
  --tecton-color-status-warning-filled-text: #1d0f01;
  --tecton-color-status-warning-filled-adornment: #1d0f01;
  --tecton-color-status-warning-filled-hover-bg: #f9a308;
  --tecton-color-status-warning-filled-pressed-bg: #fbbc3b;
  --tecton-color-status-warning-outline-bg: #00000000;
  --tecton-color-status-warning-outline-strong-border: #f9a308;
  --tecton-color-status-warning-outline-text: #fbbc3b;
  --tecton-color-status-warning-outline-adornment: #f9a308;
  --tecton-color-status-warning-outline-hover-border: #e59306;
  --tecton-color-status-warning-outline-pressed-border: #fbbc3b;

  --tecton-color-status-info-main: #8ca7de;
  --tecton-color-status-info-bright: #b7c9eb;
  --tecton-color-status-info-muted: #3766c4;
  --tecton-color-status-info-filled-bg: #6086d2;
  --tecton-color-status-info-filled-text: #0a1324;
  --tecton-color-status-info-filled-adornment: #1d3566;
  --tecton-color-status-info-filled-hover-bg: #7495d8;
  --tecton-color-status-info-filled-pressed-bg: #8ca7de;
  --tecton-color-status-info-outline-bg: #00000000;
  --tecton-color-status-info-outline-strong-border: #a0b6e4;
  --tecton-color-status-info-outline-text: #b7c9eb;
  --tecton-color-status-info-outline-adornment: #a0b6e4;
  --tecton-color-status-info-outline-hover-border: #8ca7de;
  --tecton-color-status-info-outline-pressed-border: #b7c9eb;

  --tecton-color-status-neutral-main: #959497;
  --tecton-color-status-neutral-bright: #c8c7ca;
  --tecton-color-status-neutral-muted: #6a696c;
  --tecton-color-status-neutral-filled-bg: #2c2b2e;
  --tecton-color-status-neutral-filled-text: #c8c7ca;
  --tecton-color-status-neutral-filled-adornment: #b6b5b8;
  --tecton-color-status-neutral-filled-hover-bg: #4b4a4d;
  --tecton-color-status-neutral-filled-pressed-bg: #545356;
  --tecton-color-status-neutral-outline-bg: #00000000;
  --tecton-color-status-neutral-outline-strong-border: #b6b5b8;
  --tecton-color-status-neutral-outline-text: #c8c7ca;
  --tecton-color-status-neutral-outline-adornment: #b6b5b8;
  --tecton-color-status-neutral-outline-hover-border: #a5a4a7;
  --tecton-color-status-neutral-outline-pressed-border: #c8c7ca;

  /* ---------------------------------------------------------------------- */
  /* Accents — semantic.color.accent.<name>.{main,contrastText}              */
  /* ---------------------------------------------------------------------- */
  --tecton-color-accent-lemon-main: #9e9813;
  --tecton-color-accent-lemon-contrast: #d6ce1a;
  --tecton-color-accent-graphite-main: #98939d;
  --tecton-color-accent-graphite-contrast: #cac6ce;
  --tecton-color-accent-pink-main: #c2867a;
  --tecton-color-accent-pink-contrast: #e1c3bd;
  --tecton-color-accent-saffron-main: #cb8553;
  --tecton-color-accent-saffron-contrast: #e5c2a9;
  --tecton-color-accent-lime-main: #84a138;
  --tecton-color-accent-lime-contrast: #b0d54e;
  --tecton-color-accent-blue-main: #8ca7de;
  --tecton-color-accent-blue-contrast: #b7c9eb;
  --tecton-color-accent-azure-main: #29a6a6;
  --tecton-color-accent-azure-contrast: #68d9d9;

  /* ---------------------------------------------------------------------- */
  /* Component tokens — semantic.component.*                                 */
  /* ---------------------------------------------------------------------- */
  /* table */
  --tecton-color-component-table-cell-bg: #1d1c1f;
  --tecton-color-component-table-cell-bg-alt: #323134;
  --tecton-color-component-table-cell-active-bg: #4e4853;
  --tecton-color-component-table-cell-hover-bg: #3a343e;
  --tecton-color-component-table-header-bg: #433d47;
  --tecton-color-component-table-footer: #28232c;

  /* top nav */
  --tecton-color-component-top-nav-solid-bg: #000000;
  --tecton-color-component-top-nav-contrast-text: #ffffff80;
  --tecton-color-component-top-nav-adornment: #90809e;

  /* input / filled */
  --tecton-color-component-input-filled-bg: #28232c;
  --tecton-color-component-input-filled-contrast-text: #aaa1b2;
  --tecton-color-component-input-filled-hover-bg: #342f39;
  --tecton-color-component-input-filled-focus-bg: #342f39;
  --tecton-color-component-input-filled-pressed-bg: #3a343e;
  --tecton-color-component-input-filled-active-bg: #3a343e;
  --tecton-color-component-input-filled-hover-contrast-text: #cac5d2;
  --tecton-color-component-input-filled-focus-contrast-text: #cac5d2;
  --tecton-color-component-input-filled-pressed-contrast-text: #e3e0e8;
  --tecton-color-component-input-filled-active-contrast-text: #d8d6dc;
  --tecton-color-component-input-filled-hover-adornment: #aaa1b2;
  --tecton-color-component-input-filled-focus-adornment: #aaa1b2;
  --tecton-color-component-input-filled-pressed-adornment: #cac5d2;
  --tecton-color-component-input-filled-active-adornment: #bab3c0;
  --tecton-color-component-input-filled-adornment: #8b8293;
  --tecton-color-component-input-filled-value-text: #f7f6f8;
  --tecton-color-component-input-filled-placeholder-text: #98939d;

  /* input / outlined */
  --tecton-color-component-input-outlined-bg: #00000000;
  --tecton-color-component-input-outlined-border: #57515c;
  --tecton-color-component-input-outlined-contrast-text: #98939d;
  --tecton-color-component-input-outlined-value-text: #f7f6f8;
  --tecton-color-component-input-outlined-placeholder-text: #89848e;
  --tecton-color-component-input-outlined-adornment: #8b8293;
  --tecton-color-component-input-outlined-active-bg: #1e1922;
  --tecton-color-component-input-outlined-hover-contrast-text: #cac5d2;
  --tecton-color-component-input-outlined-focus-contrast-text: #cac5d2;
  --tecton-color-component-input-outlined-pressed-contrast-text: #e3e0e8;
  --tecton-color-component-input-outlined-active-contrast-text: #d8d5de;
  --tecton-color-component-input-outlined-hover-adornment: #aaa1b2;
  --tecton-color-component-input-outlined-focus-adornment: #aaa1b2;
  --tecton-color-component-input-outlined-pressed-adornment: #cac5d2;
  --tecton-color-component-input-outlined-active-adornment: #bab3c0;
  --tecton-color-component-input-outlined-hover-border: #a7a2ac;
  --tecton-color-component-input-outlined-focus-border: #a7a2ac;
  --tecton-color-component-input-outlined-pressed-border: #b8b4bc;
  --tecton-color-component-input-outlined-active-border: #b8b4bc;

  /* input / text-only */
  --tecton-color-component-input-text-only-contrast-text: #98939d;
  --tecton-color-component-input-text-only-value-text: #f7f6f8;
  --tecton-color-component-input-text-only-placeholder-text: #89848e;
  --tecton-color-component-input-text-only-adornment: #8b8293;
  --tecton-color-component-input-text-only-focus-bg: #1e1922;
  --tecton-color-component-input-text-only-hover-contrast-text: #cac6ce;
  --tecton-color-component-input-text-only-focus-contrast-text: #cac6ce;
  --tecton-color-component-input-text-only-pressed-contrast-text: #e3e1e7;
  --tecton-color-component-input-text-only-active-contrast-text: #d8d6dc;
  --tecton-color-component-input-text-only-hover-adornment: #aaa1b2;
  --tecton-color-component-input-text-only-focus-adornment: #aaa1b2;
  --tecton-color-component-input-text-only-pressed-adornment: #cac5d2;
  --tecton-color-component-input-text-only-active-adornment: #bab3c0;

  /* avatar / badge */
  --tecton-color-component-avatar-fill: #c2867a;
  --tecton-color-component-avatar-contrast-text: #131214;
  --tecton-color-component-avatar-disabled-fill: #545356;
  --tecton-color-component-badge-contrast-text: #131214;

  /* ---------------------------------------------------------------------- */
  /* Spacing — foundational.scale.space.* (scientific density set)           */
  /* ---------------------------------------------------------------------- */
  --tecton-space-0: 0px;
  --tecton-space-25: 2px;
  --tecton-space-50: 4px;
  --tecton-space-75: 6px;
  --tecton-space-100: 8px;
  --tecton-space-150: 12px;
  --tecton-space-200: 16px;
  --tecton-space-250: 20px;
  --tecton-space-300: 24px;
  --tecton-space-400: 32px;
  --tecton-space-500: 40px;
  --tecton-space-600: 48px;
  --tecton-space-700: 56px;
  --tecton-space-800: 64px;
  --tecton-space-900: 72px;
  --tecton-space-1000: 80px;
  --tecton-space-1200: 96px;
  --tecton-space-1400: 112px;
  --tecton-space-1600: 128px;
  --tecton-space-1800: 144px;

  /* ---------------------------------------------------------------------- */
  /* Corner radii — foundational.scale.borderRadius.* (default = radius-50)  */
  /* ---------------------------------------------------------------------- */
  --tecton-radius-0: 0px;
  --tecton-radius-25: 2px;
  --tecton-radius-50: 4px;
  --tecton-radius-100: 8px;
  --tecton-radius-150: 12px;
  --tecton-radius-200: 16px;
  --tecton-radius-round: 1000px;

  /* ---------------------------------------------------------------------- */
  /* Typography — Figtree for interface text, IBM Plex Mono for data/code    */
  /* ---------------------------------------------------------------------- */
  --tecton-font-family-sans: "Figtree Variable", Figtree, ui-sans-serif, system-ui, sans-serif;
  --tecton-font-family-mono: "IBM Plex Mono", ui-monospace, monospace;

  /* displays and headings (weight 500) */
  --tecton-typography-display1-size: 3rem;
  --tecton-typography-display1-weight: 500;
  --tecton-typography-display1-line-height: 1.2083333333333333;
  --tecton-typography-display2-size: 2.5rem;
  --tecton-typography-display2-weight: 500;
  --tecton-typography-display2-line-height: 1.2;
  --tecton-typography-display3-size: 2rem;
  --tecton-typography-display3-weight: 500;
  --tecton-typography-display3-line-height: 1.1875;
  --tecton-typography-heading1-size: 1.5rem;
  --tecton-typography-heading1-weight: 500;
  --tecton-typography-heading1-line-height: 1.25;
  --tecton-typography-heading2-size: 1.25rem;
  --tecton-typography-heading2-weight: 500;
  --tecton-typography-heading2-line-height: 1.2;

  /* interface text */
  --tecton-typography-large-size: 1rem;
  --tecton-typography-large-weight: 500;
  --tecton-typography-large-line-height: 1.25;
  --tecton-typography-medium-size: 0.875rem;
  --tecton-typography-medium-weight: 400;
  --tecton-typography-medium-line-height: 1.2857142857142858;
  --tecton-typography-medium-strong-size: 0.875rem;
  --tecton-typography-medium-strong-weight: 500;
  --tecton-typography-medium-strong-line-height: 1.2857142857142858;
  --tecton-typography-small-size: 0.75rem;
  --tecton-typography-small-weight: 400;
  --tecton-typography-small-line-height: 1.3333333333333333;
  --tecton-typography-small-strong-size: 0.75rem;
  --tecton-typography-small-strong-weight: 500;
  --tecton-typography-small-strong-line-height: 1.3333333333333333;
  --tecton-typography-tiny-size: 0.625rem;
  --tecton-typography-tiny-weight: 500;
  --tecton-typography-tiny-line-height: 1.4;

  /* data readouts (IBM Plex Mono, tabular numbers) */
  --tecton-typography-large-data-size: 1rem;
  --tecton-typography-large-data-weight: 400;
